={{ (() => {
  let p = {};
  try { p = $('Filter: My Chat Only').first().json || {}; } catch (e) { p = {}; }
  let s = {};
  try { s = $('Parse Strategy Output').first().json || {}; } catch (e) { s = {}; }
  let t = {};
  try { t = $('Parse Topic Analyzer Output').first().json || {}; } catch (e) { t = {}; }

  let staticData = {};
  try { staticData = $getWorkflowStaticData('global') || {}; } catch (e) { staticData = {}; }
  const custom = staticData.userSelectedCustomSettings || {};

  let waitItem = {};
  try {
    const rawWait = $('Wait for Scenes Approval').first().json || {};
    waitItem = rawWait.body || rawWait.query || rawWait || {};
  } catch (e) { waitItem = {}; }

  let merged = [];
  try { merged = $('Merge Hybrid Scenes').all() || []; } catch (e) { merged = []; }

  const rows = [];
  for (let i = 0; i < merged.length; i++) {
    const d = (merged[i] && merged[i].json) ? merged[i].json : {};
    const url = String(d.url || '');
    if (url.indexOf('http') !== 0) continue;
    rows.push({
      n: Number(d.sceneNumber) || (i + 1),
      url: url,
      dur: Number(d.duration) || 15,
      vo: String(d.voiceoverText || '')
    });
  }
  rows.sort(function (a, b) { return a.n - b.n; });

  const allVoiceover = rows.map(r => r.vo).join(' ');
  const lang = String(s.language || t.language || p.language || 'English').toLowerCase();

  // Unicode Range \u0900-\u097F represents Devanagari (Hindi, Marathi, Nepali, Sanskrit)
  const hasDevanagari = /[\u0900-\u097F]/.test(allVoiceover) || lang.indexOf('hindi') !== -1 || lang.indexOf('hinglish') !== -1;
  const subLang = hasDevanagari ? 'hi' : 'en';

  // 1. DYNAMIC VOICE RESOLUTION
  const VOICE_MAP = {
    'adam': 'pNInz6obpgDQGcFmaJgB',
    'rachel': '21m00Tcm4TlvDq8ikWAM',
    'marcus': 'onwK4e9ZLuTAKqWW03F9',
    'aarav': 'ErXwobaYiN019PkySvjV',
    'priya': 'EXAVITQu4vr4xnSDxMaL',
    'charlie': 'IKne3meq5aSn9XLyUdCD',
    'george': 'JBFqnCBsd6RMkjVDRZzb',
    'callum': 'N2lVS1w4EtoT3dr4eOWO',
    'sarah': 'EXAVITQu4vr4xnSDxMaL',
    'charlotte': 'XB0fDUnXU5powFXDhCwa',
    'josh': 'TxGEqnHWrfWFTfGW9XjX',
    'arnold': 'VR6AewLTigWG4xSOukaG',
    'domi': 'AZnzlk1XvdvUeBnXmlld',
    'elli': 'MF3mGyEYCl7XYWbV9V6O',
    'antoni': 'ErXwobaYiN019PkySvjV',
    'bella': 'EXAVITQu4vr4xnSDxMaL',
    'brian': 'nPczCjzI2devNBz1zQrb',
    'daniel': 'onwK4e9ZLuTAKqWW03F9',
    'emily': 'LcfcDJNigL5wcS5z9bmt',
    'ethan': 'g5CIjZEefAph4nQFvHAz',
    'freya': 'jsCqWAovK2LkecY7zXl4',
    'giggle': 'MF3mGyEYCl7XYWbV9V6O',
    'glinda': 'z9fAnlkpzviPz146aGWa',
    'grace': 'oWAxZDx7w5VEj9dCyTzz',
    'harry': 'SOYHLrjzK2X1ezoY6cvb',
    'james': 'ZQe5CZNOzWyzPSCn5a3c',
    'jeremy': 'bVMeCyTHy58xNoL34h3p',
    'jessie': 't0jbNlEBZNuSJaPyNmEY',
    'joseph': 'Zlb1dXrM653N07WRdFW3',
    'liam': 'TX3LPaxmHKxFdv7VOQHJ',
    'matilda': 'XrExE9yKIg1WjnnlVkGX',
    'michael': 'flq6f7yk4E4fJM5XTYTV',
    'nicole': 'piTKgcLEGmPE4e6mEKli',
    'patrick': 'ODq5zmih8GrVes37Dizd',
    'sam': 'yoZ06aMxZJJ28mfd3POQ',
    'serena': 'pMsXgjiT309w3j25d482'
  };

  const rawVoice = String(custom.elevenLabsVoiceId || waitItem.elevenLabsVoiceId || custom.voiceId || waitItem.voiceId || p.elevenLabsVoiceId || p.voiceId || 'adam').trim();
  const voice = /^[A-Za-z0-9_-]{18,}$/.test(rawVoice) ? rawVoice : (VOICE_MAP[rawVoice.toLowerCase()] || 'pNInz6obpgDQGcFmaJgB');

  // Dynamic Voice Speed (Fallback 1.30, safe 1.10 - 1.50 range)
  const rawSpeed = custom.voiceSpeed !== undefined ? custom.voiceSpeed : (waitItem.voiceSpeed !== undefined ? waitItem.voiceSpeed : (p.voiceSpeed !== undefined ? p.voiceSpeed : 1.30));
  const parsedSpeed = Number(rawSpeed);
  const safeSpeed = isFinite(parsedSpeed) && parsedSpeed > 0 ? parsedSpeed : 1.30;
  const voiceSpeed = Math.max(1.10, Math.min(1.50, Number(safeSpeed.toFixed(2))));

  // 2. DYNAMIC SUBTITLE STYLES RESOLUTION
  let userSubs = custom.subtitleSettings || waitItem.subtitleSettings || p.subtitleSettings || {};
  if (typeof userSubs === 'string') {
    try { userSubs = JSON.parse(userSubs); } catch(e) { userSubs = {}; }
  }

  const subStyle = userSubs.style || 'highlight';

  // Automatically enforce Devanagari font when Devanagari script is present to prevent tofu [][][][] boxes
  let subFont = userSubs.fontFamily;
  let allCaps = userSubs.allCaps !== undefined ? Boolean(userSubs.allCaps) : true;

  if (hasDevanagari) {
    if (!subFont || ['Montserrat', 'Inter', 'Bebas Neue', 'Luckiest Guy', 'Bangers', 'Oswald', 'Permanent Marker'].includes(subFont)) {
      subFont = 'Noto Sans Devanagari';
    }
    allCaps = false; // Devanagari does not have uppercase; disabling prevents font glyph corruption
  } else {
    subFont = subFont || 'Montserrat';
  }

  let rawFontSize = Number(userSubs.fontSize) || 78;
  if (rawFontSize > 120) rawFontSize = Math.round(rawFontSize / 3.5);
  const subSize = Math.max(56, Math.min(100, rawFontSize));

  const subWordColor = userSubs.wordColor || '#FFE600';
  const subLineColor = userSubs.lineColor || '#FFFFFF';
  const subOutlineColor = userSubs.outlineColor || '#000000';
  const subOutlineWidth = Number(userSubs.outlineWidth !== undefined ? userSubs.outlineWidth : 8);
  const subPos = userSubs.position || 'center-bottom';
  const maxWords = Number(userSubs.maxWordsPerLine) || 3;

  const subSettings = {
    'font-family': subFont,
    'font-size': subSize,
    'font-weight': '900',
    'position': subPos,
    'line-color': subLineColor,
    'word-color': subWordColor,
    'outline-color': subOutlineColor,
    'outline-width': subOutlineWidth,
    'max-words-per-line': maxWords,
    'all-caps': allCaps,
    'style': subStyle === 'classic-progressive' ? 'highlight' : subStyle
  };
  if (userSubs.boxColor && userSubs.boxColor.trim()) subSettings['box-color'] = userSubs.boxColor.trim();
  if (userSubs.fontUrl) subSettings['font-url'] = String(userSubs.fontUrl);

  // 3. DYNAMIC BACKGROUND MUSIC RESOLUTION
  const bgmUrl = custom.musicTrackUrl !== undefined ? custom.musicTrackUrl : (waitItem.musicTrackUrl !== undefined ? waitItem.musicTrackUrl : (p.musicTrackUrl !== undefined ? p.musicTrackUrl : 'https://bangai.netlify.app/music/mystery2.mp3'));
  const rawVol = custom.musicVolume !== undefined ? custom.musicVolume : (waitItem.musicVolume !== undefined ? waitItem.musicVolume : (p.musicVolume !== undefined ? p.musicVolume : 0.08));
  const parsedVol = Number(rawVol);
  const bgmVolume = isFinite(parsedVol) ? Math.max(0, Math.min(0.4, parsedVol)) : 0.08;

  const topElements = [
    {
      type: 'subtitles',
      model: 'whisper',
      language: subLang,
      settings: subSettings
    }
  ];

  if (bgmUrl && String(bgmUrl).trim() !== '' && bgmVolume > 0) {
    topElements.push({
      type: 'audio',
      src: String(bgmUrl).trim(),
      volume: bgmVolume,
      loop: -1,
      duration: -2,
      'fade-out': 2
    });
  }

  const scenes = rows.map(function (r) {
    return {
      duration: r.dur,
      transition: { style: 'fade', duration: 0.3 },
      elements: [
        {
          type: 'video',
          src: r.url,
          'keep-audio': false,
          volume: 0,
          'aspect-ratio': '9:16',
          width: 1080,
          height: 1920,
          fit: 'cover',
          duration: -1,
          speed: 1.0
        },
        {
          type: 'voice',
          voice: voice,
          text: r.vo,
          model: 'elevenlabs',
          speed: voiceSpeed
        }
      ]
    };
  });

  return JSON.stringify({
    resolution: 'instagram-story',
    quality: 'high',
    elements: topElements,
    scenes: scenes
  });
})() }}

