const savedData = staticData['savedVideoPrompt_' + sceneNum] || {};
return { json: { videoUrl, status: 'completed', provider: 'backup', sceneIndex: savedData.sceneIndex ?? inputData.sceneIndex, sceneNumber: savedData.sceneNumber ?? sceneNum, voiceoverText: savedData.voiceoverText ?? inputData.voiceoverText, voiceStyle: savedData.voiceStyle ?? inputData.voiceStyle, speaker: savedData.speaker ?? inputData.speaker, videoPrompt: savedData.videoPrompt ?? inputData.videoPrompt, duration: savedData.duration ?? inputData.duration, title: savedData.title ?? inputData.title, corePlot: savedData.corePlot ?? inputData.corePlot, tags: savedData.tags ?? inputData.tags, youtubeDescription: savedData.youtubeDescription ?? inputData.youtubeDescription } };

