    sceneGuidance += '\nNOTE: the scene blueprint is incomplete. Build the missing scenes yourself from the story brief, keeping the HOOK / CONTEXT / ESCALATION / PEAK / RESOLUTION structure and the 8-5-7-10-6 intensity curve.\n';
  }

  const langInstruction = language === 'English'
    ? 'WRITE EVERY voiceoverText IN PURE ENGLISH. Natural spoken English, contractions allowed, no Hindi words at all.'
    : language === 'Hindi'
    ? 'WRITE EVERY voiceoverText IN PURE HINDI, transliterated in Roman script so the voice engine pronounces it correctly. Example: Us raat ghar mein sirf ek aadmi tha, aur uske paas jawab nahi tha. No English words except unavoidable proper nouns.'
