// Rotate Backup LLM On Failure — safely rotates backup keys & stops when exhausted
const backupFallbackKeys = [
  "e8dddcdad5msh80e5a3d80b70d34p15eeffjsn5954cc89f72f",
  "c822c4293emsh61f15bb9eeabb99p14956cjsn1fa2f74ad9f1",
  "2b015b49e7msha9808f1d1ae6654p178d39jsn886507cf88a8",
  "54df5cbe66msh5a2f44867ada346p18df76jsn336df21434a7",
  "c056caf42emsh31e2a3a34483eb4p19cccfjsn41c571dc31bd"
];

let keys = backupFallbackKeys;
try {
  const master = $('Config: Backup LLM Master').first().json;
  if (master && master.keys && master.keys.length > 0) keys = master.keys;
} catch(e) {}

let staticData = $getWorkflowStaticData('global');
const totalKeys = keys.length;
const firstItem = $input.first() || { json: {} };

if (staticData.fruitBackupLlmAttempts === undefined) {
  staticData.fruitBackupLlmAttempts = 0;
}

staticData.fruitBackupLlmAttempts += 1;

if (staticData.fruitBackupLlmAttempts >= totalKeys) {
  console.log(`All ${totalKeys} backup LLM API keys exhausted. Stopping workflow.`);
  staticData.fruitBackupLlmIndex = 0;
  staticData.fruitBackupLlmAttempts = 0;
  staticData.fruitUseBackupLlm = false;

  throw new Error(`All backup LLM API keys (${totalKeys}) have been exhausted. Please add more API keys or try again later.`);
}

staticData.fruitBackupLlmIndex = (staticData.fruitBackupLlmIndex || 0) + 1;
console.log(`Backup LLM Attempt ${staticData.fruitBackupLlmAttempts}/${totalKeys}: Rotating to key index ${staticData.fruitBackupLlmIndex}`);

return [firstItem];

// Handle Backup LLM Success v5.0 — Clean 4-Key Schema | NO imagePrompt | NO visualPrompt
function extractContent(response) {
  if (!response) return '';
  const r = Array.isArray(response) ? response[0] : response;
  if (!r) return '';
  if (r.choices && r.choices[0]) return r.choices[0].message?.content || r.choices[0].text || '';
  if (r.data && r.data.choices && r.data.choices[0]) return r.data.choices[0].message?.content || '';
  if (r.output && Array.isArray(r.output) && r.output[0]) {
    const f = r.output[0];
    if (f.content && Array.isArray(f.content) && f.content[0] && f.content[0].text) return f.content[0].text;
    if (f.message && f.message.content) return f.message.content;
    if (f.text) return f.text;
    if (typeof f === 'string') return f;
  }
  if (r.output) return typeof r.output === 'string' ? r.output : JSON.stringify(r.output);
  return r.content || r.response || r.text || (typeof r === 'string' ? r : JSON.stringify(r));
}

function masterCleanAndParseJSON(raw) {
  if (!raw) return null;
