// ---------- v7: preserve the FULL brief (no whitelist) ----------
let sheetRows = [];
try { sheetRows = $('Read Past Topics').all().map(i => i.json || {}); } catch (e) { sheetRows = []; }
const recentRows = sheetRows.slice(-40);
const pickCol = (row, ...names) => {
