parameters.jsonBody:
={{ (() => {
  let topicData = {};
  try { topicData = $('Parse Topic Analyzer Output').first().json || {}; } catch(e) { topicData = {}; }
  const mem = $json || {};

  const rawInput        = topicData.rawUserInput   || mem.rawUserInput || '';
