// Parse Refined Story Output v2 — strict JSON, selective-refine aware
const raw = $input.first().json?.output || $input.first().json?.text || '';

let s = {};  try { s = $('Parse Strategy Output').first().json || {}; } catch(e) {}
let t = {};  try { t = $('Parse Topic Analyzer Output').first().json || {}; } catch(e) {}
let p = {};  try { p = $('Filter: My Chat Only').first().json || {}; } catch(e) {}

let prev = {};
try { prev = $getWorkflowStaticData('global').lastRefinedStory || {}; } catch(e) {}

const base = {
  suggestedTitle: prev.suggestedTitle || s.suggestedTitle || t.specificTopic || 'Viral Video',
  viralHook:      prev.viralHook      || s.viralHook      || '',
  storyBrief:     prev.storyBrief     || s.storyBrief     || ''
};

function extractJson(text) {
  if (!text) return null;
  let str = String(text).trim();
  const fence = str.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) str = fence[1].trim();
  const a = str.indexOf('{'), b = str.lastIndexOf('}');
  if (a === -1 || b === -1 || b <= a) return null;
  str = str.substring(a, b + 1);
  try { return JSON.parse(str); } catch (e) {}
  try { return JSON.parse(str.replace(/,\s*([}\]])/g, '$1')); } catch (e) {}
  return null;
}

const parsed = extractJson(raw);
let refineFailed = false, failReason = '';
let out = { ...base }, changedFields = [], changeSummary = '';

if (parsed) {
  if (parsed.suggestedTitle) out.suggestedTitle = String(parsed.suggestedTitle).trim();
  if (parsed.viralHook)      out.viralHook      = String(parsed.viralHook).trim();
  if (parsed.storyBrief)     out.storyBrief     = String(parsed.storyBrief).trim();
  changedFields = Array.isArray(parsed.changedFields) ? parsed.changedFields : [];
  changeSummary = parsed.changeSummary || '';
} else {
  // legacy text fallback
  const m1 = raw.match(/Title:\s*([^\n\r]+)/i);
  const m2 = raw.match(/Hook:\s*["']?([^"\n\r]+)["']?/i);
  const m3 = raw.match(/Story Brief:\s*([\s\S]+)/i);
  if (m1) out.suggestedTitle = m1[1].trim();
  if (m2) out.viralHook = m2[1].trim();
  if (m3) out.storyBrief = m3[1].trim();
  if (!m1 && !m2 && !m3) { refineFailed = true; failReason = 'Agent returned unparseable output'; }
  changeSummary = 'Parsed from plain text (agent did not return JSON)';
}

const payload = {
  status: 'READY_FOR_APPROVAL',
  stage: 'STORY_APPROVAL',
  suggestedTitle: out.suggestedTitle,
  title: out.suggestedTitle,
  viralHook: out.viralHook,
  storyBrief: out.storyBrief,
  topic: t.specificTopic || p.rawUserInput || '',
  genre: t.genre || s.contentType || 'Viral Short',
  visualStyle: s.visualStyle || p.visualStyle || 'Cinematic Realistic',
  language: s.language || p.language || 'English',
  characterBible: s.characterBible || '',
  refined: true,
  refineFailed,
  failReason,
  changedFields,
  changeSummary,
  refineTimestamp: new Date().toISOString()
};

const sd = $getWorkflowStaticData('global');
sd.lastRefinedStory = { suggestedTitle: payload.suggestedTitle, viralHook: payload.viralHook, storyBrief: payload.storyBrief };

return [{ json: payload }];

