// Parse Refined Scenes Output v2 — strict JSON, per-field merge, no silent revert
const raw = $input.first().json?.output || $input.first().json?.text || '';
const sd = $getWorkflowStaticData('global');

let baseScenes = [];
try { baseScenes = (sd.islamicFullScript && sd.islamicFullScript.scenes) || []; } catch(e) {}
if (!baseScenes.length) {
  try { baseScenes = $('Split Scenes').all().map(i => i.json); } catch(e) { baseScenes = []; }
}

function extractJson(text) {
  if (!text) return null;
  let str = String(text).trim();
  const fence = str.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) str = fence[1].trim();
  let a = str.indexOf('{'), b = str.lastIndexOf('}');
  const a2 = str.indexOf('['), b2 = str.lastIndexOf(']');
  if (a2 !== -1 && (a === -1 || a2 < a)) { a = a2; b = b2; }
  if (a === -1 || b === -1 || b <= a) return null;
  str = str.substring(a, b + 1);
  try { return JSON.parse(str); } catch (e) {}
  try { return JSON.parse(str.replace(/,\s*([}\]])/g, '$1')); } catch (e) {}
  return null;
}

let parsed = extractJson(raw);
if (Array.isArray(parsed)) parsed = { scenes: parsed };

let refineFailed = false, failReason = '', changedScenes = [], changeSummary = '';
let finalScenes = baseScenes.map(s => ({ ...s }));

if (parsed && Array.isArray(parsed.scenes) && parsed.scenes.length) {
  parsed.scenes.forEach(ns => {
    const num = parseInt(ns.sceneNumber || ns.scene || 0, 10);
    const idx = num >= 1 && num <= finalScenes.length ? num - 1 : -1;
    if (idx === -1) return;
    const vo  = (ns.voiceoverText || '').toString().trim();
    const vid = (ns.videoPrompt   || '').toString().trim();
    if (vo)  finalScenes[idx].voiceoverText = vo;
    if (vid) finalScenes[idx].videoPrompt   = vid;
    finalScenes[idx].duration = 15;
  });
  changedScenes = Array.isArray(parsed.changedScenes) ? parsed.changedScenes : [];
  changeSummary = parsed.changeSummary || '';
} else {
  refineFailed = true;
  failReason = 'Screenplay Doctor returned unparseable output — original scenes kept';
}

sd.islamicFullScript = sd.islamicFullScript || {};
sd.islamicFullScript.scenes = finalScenes;

return finalScenes.map((s, idx) => ({
  json: {
    ...s,
    sceneIndex: idx,
    sceneNumber: idx + 1,
    duration: 15,
    voiceoverCharCount: (s.voiceoverText || '').length,
    refined: true,
    refineFailed,
    failReason,
    changedScenes,
    changeSummary
  }
}));

// Select a randomized engaging comment for manual YouTube upload
let ytData = {};
try { ytData = $('Dynamic User YouTube Upload (Manual)').first().json || {}; } catch(e) {}
const videoId = ytData.uploadId || ytData.id || $input.first()?.json?.uploadId || $input.first()?.json?.id;

if (!videoId) {
  return [{ json: { skipped: true, reason: 'no videoId' } }];
}

const comments = [
  "😢 Yeh kahani dil ko chhu gayi! Comment karo agar aapko bhi emotional laga aur Subscribe karo 🔔",
  "💔 Zindagi ke aakhri 24 ghante... kitne keemti hote hain! Comment mein apne thoughts share karo 👇",
  "⏰ Agar aapke paas sirf 24 ghante ho toh kya karoge? Comment karein aur Subscribe karo 🔔",
  "😭 Is video ne aankhon mein aansu la diye! Like karo agar aapko bhi laga aur Share karo ❤️",
  "🕰️ Har pal keemti hai! Yeh kahani sunkar kya seekha? Comment mein likho 👇",
  "💫 Zindagi mein kya zaroori hai? Is story se pata chalta hai! Subscribe karo 🔔",
  "🌟 Aakhri 24 ghante kaise bitaye unhone? Comment karo apna reaction aur Bell bajao 🔔",
  "😔 Kya aap bhi aise hi bitate apne aakhri pal? Comment mein batayen 👇",
  "🙏 Zindagi ek tohfa hai! Is kahani ne yeh yaad dilaya! Like karo agar agree ho ❤️",
  "⌛ Time kitna keemti hai yeh video dekhkar pata chalta hai! Subscribe karo 🔔",
  "💭 Agar aapke paas bhi 24 ghante ho toh kya karoge? Comment karein 👇",
  "😢 Yeh 75 seconds ne bahut kuch sikha diya! Share karo apne loved ones ke saath ❤️",
  "🎯 Har kahani ek sabak hai! Aapko kya mila is story se? Comment karein 👇",
  "💝 Apno ke saath time bitao! Yeh video yahi sikhati hai! Subscribe karo 🔔",
  "😥 Emotional roller coaster! Kya aapko bhi feel hua? Comment YES ya NO 👇",
  "🌹 Zindagi ke aakhri pal kaise jiyen? Is story mein jawaab hai! Subscribe karo 🔔",
  "💬 Kya aapne kabhi socha hai apne aakhri din ke baare mein? Comment karein 👇",
  "🔔 Aisi aur inspiring stories ke liye Subscribe karo aur Bell icon on karo!",
  "😌 Life lessons in 75 seconds! Comment karo agar seekha kuch aur Like karo ❤️",
  "🌈 Har kahani ek naya nazariya! Agli story miss mat karo, Subscribe karo 🔔"
];

const selected = comments[Math.floor(Math.random() * comments.length)];
return [{ json: { videoId, comment: selected } }];

// Pinned comment selected for manual YouTube upload
const item = $input.first()?.json || {};
return [{
  json: {
    success: true,
    videoId: item.videoId || "",
    pinnedComment: item.comment || "",
    status: "COMMENT_PREPARED"
  }
}];

// Pinned comment selected for auto YouTube upload
const item = $input.first()?.json || {};
return [{
  json: {
    success: true,
    videoId: item.videoId || "",
    pinnedComment: item.comment || "",
    status: "COMMENT_PREPARED"
  }
}];

// Filter: My Chat Only — authenticate + normalize website payload
// (voice, speed, music, subtitles, YouTube & Google Sheets) with strict prompt validation
const raw      = $input.first().json || {};
const headers  = raw.headers || {};
const body     = raw.body || raw;
const query    = raw.query || {};
const settings = body.settings || {};

// ---------- SECURITY ----------
const VALID_SECRET = 's-vshorts-sec-9a8b7c6d5e4f3a2b1c0';
const providedSecret = headers['x-webhook-secret']
  || headers['X-Webhook-Secret']
  || body.webhookSecret
  || body.secretKey
  || query.secret
  || raw.webhookSecret;

if (providedSecret && providedSecret !== VALID_SECRET) {
  throw new Error('Unauthorized: Invalid webhook security secret');
}

// ---------- PROMPT (REQUIRED - never invent one) ----------
const rawPrompt = body.prompt || body.message || body.rawUserInput
  || query.prompt || query.message || raw.prompt || '';

if (typeof rawPrompt !== 'string' || !rawPrompt.trim()) {
  throw new Error('User prompt is required from website');
}
const prompt = rawPrompt.trim();

// ---------- LANGUAGE (typed instruction wins over website default) ----------
const lower = prompt.toLowerCase();
let language = body.language || query.language || settings.language || 'Hinglish';

if (lower.includes('in english') || lower.includes('english only') || lower.includes('only english') || lower.includes('english mein')) {
  language = 'English';
} else if (lower.includes('in hinglish') || lower.includes('hinglish only') || lower.includes('only hinglish')) {
  language = 'Hinglish';
} else if (lower.includes('in hindi') || lower.includes('hindi only') || lower.includes('only hindi') || lower.includes('hindi mein')) {
  language = 'Hindi';
}

// ---------- HELPERS ----------
const firstDefined = (...vals) => {
  for (const v of vals) if (v !== undefined && v !== null && v !== '') return v;
  return undefined;
};
const clampNum = (val, min, max, fallback) => {
  const n = Number(val);
  if (!isFinite(n)) return fallback;
  return Math.max(min, Math.min(max, n));
};

// ---------- VOICE ----------
const voiceId          = firstDefined(body.voiceId, query.voiceId, settings.voiceId) || 'adam';
const elevenLabsVoiceId = String(firstDefined(body.elevenLabsVoiceId, query.elevenLabsVoiceId, settings.elevenLabsVoiceId) || '').trim();

// 1.30 keeps a 190-200 char line inside one 15s clip. Never default below 1.10.
const voiceSpeed = clampNum(
  firstDefined(body.voiceSpeed, query.voiceSpeed, settings.voiceSpeed),
  1.10, 1.50, 1.30
);

// ---------- MUSIC (0 is a valid choice = muted) ----------
const musicId       = firstDefined(body.musicId, query.musicId, settings.musicId) || 'mystery2';
const musicTrackUrl = String(firstDefined(body.musicTrackUrl, query.musicTrackUrl, settings.musicTrackUrl) || '').trim();

let rawVolume = body.musicVolume;
if (rawVolume === undefined) rawVolume = query.musicVolume;
if (rawVolume === undefined) rawVolume = settings.musicVolume;
const musicVolume = clampNum(rawVolume, 0, 0.4, 0.08);

// ---------- SUBTITLES ----------
let subtitleSettings = firstDefined(body.subtitleSettings, query.subtitleSettings, settings.subtitleSettings) || null;
if (typeof subtitleSettings === 'string') {
  try { subtitleSettings = JSON.parse(subtitleSettings); } catch (e) { subtitleSettings = null; }
}
if (subtitleSettings && typeof subtitleSettings !== 'object') subtitleSettings = null;

// ---------- GOOGLE OAUTH: YOUTUBE & SHEETS (PASSTHROUGH) ----------
const autoUploadToYouTube     = body.autoUploadToYouTube !== undefined ? !!body.autoUploadToYouTube : (query.autoUploadToYouTube !== undefined ? !!query.autoUploadToYouTube : (settings.autoUploadToYouTube !== undefined ? !!settings.autoUploadToYouTube : false));
const userYouTubeAccessToken  = String(firstDefined(body.userYouTubeAccessToken, query.userYouTubeAccessToken, settings.userYouTubeAccessToken) || '').trim();
const userYouTubeChannelTitle = String(firstDefined(body.userYouTubeChannelTitle, query.userYouTubeChannelTitle, settings.userYouTubeChannelTitle) || '').trim();
const userYouTubeChannelId    = String(firstDefined(body.userYouTubeChannelId, query.userYouTubeChannelId, settings.userYouTubeChannelId) || '').trim();

