const threadId    = firstDefined(body.threadId, query.threadId, raw.threadId) || ('thread-' + Date.now());
const sessionId   = firstDefined(body.sessionId, query.sessionId, raw.sessionId) || 'session-default';
const callbackUrl = firstDefined(body.callbackUrl, query.callbackUrl, raw.callbackUrl)
  || 'https://bangai.netlify.app/.netlify/functions/story-approval';

return [{
