  }
}];

// Dynamic YouTube Upload Node: Uploads directly to User's Connected Channel with Token Refresh & Binary Helper
const item = $input.first();
let binaryData = item.binary?.data || Object.values(item.binary || {})[0];
let chatCtx = {};
try { chatCtx = $('Filter: My Chat Only').first().json || {}; } catch(e) {}
let splitScenes = {};
try { splitScenes = $('Split Scenes').first().json || {}; } catch(e) {}
let parseStrategy = {};
try { parseStrategy = $('Parse Strategy Output').first().json || {}; } catch(e) {}
let parseTopic = {};
try { parseTopic = $('Parse Topic Analyzer Output').first().json || {}; } catch(e) {}

let accessToken = chatCtx.userYouTubeAccessToken;

// 1. Silent token refresh before upload
if (chatCtx.threadId) {
  try {
    const refreshRes = await fetch('https://bangai.netlify.app/.netlify/functions/refresh-upload-token', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-webhook-secret': 's-vshorts-sec-9a8b7c6d5e4f3a2b1c0'
      },
      body: JSON.stringify({
        threadId: chatCtx.threadId,
        channelId: chatCtx.userYouTubeChannelId || '',
        scope: 'youtube'
      })
    });
    if (refreshRes.ok) {
      const refreshData = await refreshRes.json();
      if (refreshData.accessToken) {
        accessToken = refreshData.accessToken;
      }
    }
  } catch (refreshErr) {
    console.warn('[n8n YouTube Upload] Token refresh notice:', refreshErr.message);
  }
}

const title = (splitScenes.title || chatCtx.title || chatCtx.rawUserInput || 'Viral YouTube Short').substring(0, 100);
const description = splitScenes.youtubeDescription || chatCtx.description || '';
const tags = Array.isArray(splitScenes.tags) ? splitScenes.tags : (splitScenes.tags ? splitScenes.tags.split(',') : []);

if (!accessToken) {
  throw new Error('User YouTube OAuth access token is missing');
}

// 2. Resolve video binary buffer with robust fallback
let videoBuffer = null;
if (binaryData && binaryData.data) {
  videoBuffer = Buffer.from(binaryData.data, 'base64');
} else if (this.helpers && typeof this.helpers.getBinaryDataBuffer === 'function') {
  try {
    videoBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
  } catch (e) {
    try {
      const keys = Object.keys(item.binary || {});
      if (keys.length > 0) videoBuffer = await this.helpers.getBinaryDataBuffer(0, keys[0]);
    } catch (_) {}
  }
}

if (!videoBuffer) {
  throw new Error('Video file binary buffer could not be loaded');
}

const mimeType = binaryData?.mimeType || 'video/mp4';

const metadata = {
  snippet: {
    title: title,
    description: description,
    tags: tags.map(t => t.replace(/[<>]/g, '').trim()).filter(t => t.length > 0).slice(0, 30),
